/// <summary>
/// REQ-INV-105: puts the delivery instructions of the invoice on the sales invoice report header.
/// </summary>
[ExtensionOf(classStr(SalesInvoiceDP))]
final class SalesInvoiceDP_DYLO_Extension
{
}

Method.Source:
/// <summary>
/// Fills the report header and adds the delivery instructions of the invoice journal.
/// </summary>
/// <param name = "_custInvoiceJour">The customer invoice journal being printed.</param>
/// <param name = "_companyInfo">The legal entity.</param>
protected void populateSalesInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
{
    next populateSalesInvoiceHeaderFooterTmp(_custInvoiceJour, _companyInfo);

    salesInvoiceHeaderFooterTmp.DYLO_DeliveryInstructions = _custInvoiceJour.DYLO_DeliveryInstructions;
}
